# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make(last, first):
    return Student("id-" + last, last, first, "A")


ROSTER = [make("Halloway", "Juno"), make("Dunmere", "Piet"), make("Abbot", "Ola")]


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seating_rows(ROSTER, 2),
            ["Row 1: Abbot, Ola | Dunmere, Piet", "Row 2: Halloway, Juno"],
        )

    def test_single_long_row(self):
        lines = seating_rows(ROSTER, 10)
        self.assertEqual(len(lines), 1)

    def test_sort_ignores_case(self):
        lines = seating_rows([make("beck", "Al"), make("Aman", "Bo")], 5)
        self.assertEqual(lines, ["Row 1: Aman, Bo | beck, Al"])

    def test_input_is_not_modified(self):
        original = list(ROSTER)
        seating_rows(ROSTER, 2)
        self.assertEqual(ROSTER, original)

    def test_bad_seat_counts_raise(self):
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seating_rows(ROSTER, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
